fn install_synthetic_codex_home() {
    static HOME: OnceLock<PathBuf> = OnceLock::new();
    let home = HOME.get_or_init(|| {
        let home = std::env::temp_dir().join(format!(
            "agenticjira-synthetic-codex-home-{}",
            std::process::id()
        ));
        let codex_home = home.join(".codex");
        std::fs::create_dir_all(&codex_home).unwrap();
        std::fs::set_permissions(&home, std::fs::Permissions::from_mode(0o700)).unwrap();
        std::fs::write(
            codex_home.join("config.toml"),
            "cli_auth_credentials_store = \"file\"\n[mcp_servers]\nplain = { command = \"/synthetic/plain\" }\n\"quoted.dot\" = { command = \"/synthetic/dotted\" }\n\"rocket🚀\" = { command = \"/synthetic/unicode\" }\n[features]\nmemories = true\n",
        )
        .unwrap();
        let encode = |value: serde_json::Value| {
            base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(value.to_string())
        };
        let id_token = format!(
            "{}.{}.synthetic",
            encode(serde_json::json!({"alg":"none"})),
            encode(serde_json::json!({
                "https://api.openai.com/auth":{"chatgpt_plan_type":"pro"}
            }))
        );
        let access_token = format!(
            "{}.{}.synthetic",
            encode(serde_json::json!({"alg":"none"})),
            encode(serde_json::json!({"exp":4102444800_i64}))
        );
        std::fs::write(
            codex_home.join("auth.json"),
            serde_json::to_vec(&serde_json::json!({
                "auth_mode":"chatgpt",
                "OPENAI_API_KEY":null,
                "tokens":{
                    "id_token":id_token,
                    "access_token":access_token,
                    "refresh_token":"synthetic-refresh-token",
                    "account_id":"synthetic-account"
                },
                "last_refresh":"2099-01-01T00:00:00Z"
            }))
            .unwrap(),
        )
        .unwrap();
        home
    });
    std::env::remove_var("CODEX_HOME");
    std::env::set_var("HOME", home);
}

fn m4a_paths(label: &str) -> InstancePaths {
    let root =
        std::env::temp_dir().join(format!("agenticjira-m4a-{label}-{}", uuid::Uuid::new_v4()));
    let paths = InstancePaths::resolve(Some(root)).unwrap();
    paths.create().unwrap();
    paths
}

fn m4a_backup_path(result: &serde_json::Value) -> PathBuf {
    PathBuf::from(result["backup"].as_str().unwrap())
}

fn m4a_read_journal(paths: &InstancePaths) -> serde_json::Value {
    serde_json::from_slice(
        &std::fs::read(paths.state.join("database-restore-journal.json")).unwrap(),
    )
    .unwrap()
}

fn m4a_write_journal(paths: &InstancePaths, journal: &serde_json::Value) {
    std::fs::write(
        paths.state.join("database-restore-journal.json"),
        serde_json::to_vec_pretty(journal).unwrap(),
    )
    .unwrap();
}

fn m4a_prior_boot_identity() -> String {
    let current = agenticjira::supervisor::system_boot_identity().unwrap();
    let replacement = uuid::Uuid::new_v4();
    if current.starts_with("linux:") {
        format!("linux:{replacement}")
    } else {
        format!("darwin:bootsessionuuid:{replacement}")
    }
}

fn queued_restart_result_json(
    operation_id: &str,
    member: &str,
    replacement_failures: u64,
    capacity_deferrals: u64,
    next_due_at: Option<&str>,
) -> String {
    serde_json::json!({
        "sentinel":"preserved",
        "llmrelay_restart_v1":{
            "version":1,
            "batch":{
                "operation_id":operation_id,
                "ordinal":1,
                "members":[member],
                "membership":"queued",
            },
            "batch_history":[],
            "replacement_failures":replacement_failures,
            "capacity_deferrals":capacity_deferrals,
            "next_due_at":next_due_at,
            "admission":null,
        }
    })
    .to_string()
}

fn assert_restart_accounting(database: &std::path::Path, session: &str, expected: &str) {
    let connection = Connection::open(database).unwrap();
    let actual: String = connection
        .query_row(
            "SELECT state || ':' || json_extract(result_json,'$.llmrelay_restart_v1.batch.operation_id') || ':' ||
                    json_extract(result_json,'$.llmrelay_restart_v1.batch.membership') || ':' ||
                    json_extract(result_json,'$.llmrelay_restart_v1.replacement_failures') || ':' ||
                    json_extract(result_json,'$.llmrelay_restart_v1.capacity_deferrals') || ':' ||
                    json_extract(result_json,'$.sentinel')
             FROM restart_candidates WHERE session_id=?1",
            params![session],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(actual, expected);
}

fn m4a_assert_file_binding(path: &std::path::Path, binding: &serde_json::Value) {
    let metadata = std::fs::metadata(path).unwrap();
    assert_eq!(metadata.dev(), binding["device"].as_u64().unwrap());
    assert_eq!(metadata.ino(), binding["inode"].as_u64().unwrap());
    assert_eq!(metadata.len(), binding["bytes"].as_u64().unwrap());
    assert_eq!(
        sha256(&std::fs::read(path).unwrap()),
        binding["sha256"].as_str().unwrap()
    );
}

fn m4a_recreate_verified_boundary(paths: &InstancePaths, journal: &mut serde_json::Value) {
    let staged = PathBuf::from(journal["staged_database"].as_str().unwrap());
    std::fs::rename(&paths.database, &staged).unwrap();
    let backup = PathBuf::from(journal["backup_database"].as_str().unwrap());
    let backup_bytes = std::fs::read(backup).unwrap();
    let mut staged_file = std::fs::OpenOptions::new()
        .write(true)
        .truncate(true)
        .open(&staged)
        .unwrap();
    staged_file.write_all(&backup_bytes).unwrap();
    staged_file.sync_all().unwrap();
    drop(staged_file);
    for item in journal["moves"].as_array_mut().unwrap() {
        let source = PathBuf::from(item["source"].as_str().unwrap());
        let quarantine = PathBuf::from(item["quarantine"].as_str().unwrap());
        if source != paths.database && source.exists() {
            std::fs::remove_file(&source).unwrap();
        }
        match item["disposition"].as_str().unwrap() {
            "moved" => std::fs::rename(quarantine, source).unwrap(),
            "absent" => assert!(!source.exists()),
            disposition => panic!("unexpected completed move disposition {disposition}"),
        }
        item["disposition"] = serde_json::Value::Null;
    }
    m4a_assert_file_binding(&staged, &journal["staged_binding"]);
    for binding in journal["live_family_before"].as_array().unwrap() {
        m4a_assert_file_binding(
            std::path::Path::new(binding["path"].as_str().unwrap()),
            binding,
        );
    }
    journal["installed"] = serde_json::Value::Bool(false);
    journal["phase"] = serde_json::Value::String("verified".into());
    m4a_write_journal(paths, journal);
}

fn m4a_assert_recovered_restore(paths: &InstancePaths, journal: &serde_json::Value) {
    assert_eq!(m4a_read_journal(paths)["phase"], "completed");
    assert_eq!(database::check(paths).unwrap()["integrity"], "ok");
    let staged = PathBuf::from(journal["staged_database"].as_str().unwrap());
    for suffix in ["-wal", "-shm"] {
        let sidecar = PathBuf::from(format!("{}{suffix}", staged.display()));
        assert!(
            !sidecar.exists(),
            "staged verifier left {}",
            sidecar.display()
        );
    }
    let live_metadata = std::fs::metadata(&paths.database).unwrap();
    assert_eq!(
        live_metadata.dev(),
        journal["staged_binding"]["device"].as_u64().unwrap()
    );
    assert_eq!(
        live_metadata.ino(),
        journal["staged_binding"]["inode"].as_u64().unwrap()
    );
    let quarantine = PathBuf::from(journal["quarantine"].as_str().unwrap());
    for binding in journal["live_family_before"].as_array().unwrap() {
        let source = PathBuf::from(binding["path"].as_str().unwrap());
        m4a_assert_file_binding(&quarantine.join(source.file_name().unwrap()), binding);
    }
}

fn m4a_prepare_installing_boundary(paths: &InstancePaths, journal: &mut serde_json::Value) {
    m4a_recreate_verified_boundary(paths, journal);
    for item in journal["moves"].as_array_mut().unwrap() {
        let source = PathBuf::from(item["source"].as_str().unwrap());
        if source.exists() {
            std::fs::rename(&source, PathBuf::from(item["quarantine"].as_str().unwrap())).unwrap();
            item["disposition"] = serde_json::Value::String("moved".into());
        } else {
            item["disposition"] = serde_json::Value::String("absent".into());
        }
    }
    journal["phase"] = serde_json::Value::String("installing".into());
    m4a_write_journal(paths, journal);
}

fn m4a_prepare_hold_pending_boundary(paths: &InstancePaths, journal: &mut serde_json::Value) {
    m4a_prepare_installing_boundary(paths, journal);
    std::fs::rename(
        PathBuf::from(journal["staged_database"].as_str().unwrap()),
        &paths.database,
    )
    .unwrap();
    journal["installed"] = serde_json::Value::Bool(true);
    journal["phase"] = serde_json::Value::String("hold_pending".into());
    m4a_write_journal(paths, journal);
}

fn m4a_restore_file_snapshot(
    paths: &InstancePaths,
    journal: &serde_json::Value,
) -> Vec<(PathBuf, Option<Vec<u8>>)> {
    let mut files = vec![
        paths.state.join("database-restore-journal.json"),
        PathBuf::from(journal["staged_database"].as_str().unwrap()),
    ];
    for item in journal["moves"].as_array().unwrap() {
        files.push(PathBuf::from(item["source"].as_str().unwrap()));
        files.push(PathBuf::from(item["quarantine"].as_str().unwrap()));
    }
    files.sort();
    files.dedup();
    files
        .into_iter()
        .map(|path| {
            let bytes = match std::fs::read(&path) {
                Ok(bytes) => Some(bytes),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
                Err(error) => panic!("snapshot {}: {error}", path.display()),
            };
            (path, bytes)
        })
        .collect()
}

fn m4a_assert_recovery_refusal_preserves_files(
    paths: &InstancePaths,
    journal: &serde_json::Value,
    expected_error: &str,
) {
    let before = m4a_restore_file_snapshot(paths, journal);
    let error = database::recover_interrupted_restore_locked(paths)
        .unwrap_err()
        .to_string();
    assert!(
        error.contains(expected_error),
        "unexpected refusal: {error}"
    );
    assert_eq!(m4a_restore_file_snapshot(paths, journal), before);
}

#[test]
fn m4a_readonly_commands_neither_create_nor_migrate() {
    let paths = m4a_paths("readonly");
    assert!(!paths.database.exists());
    let missing = database::inspect(&paths).unwrap_err().to_string();
    assert!(missing.contains("read-only") || missing.contains("unable to open"));
    assert!(!paths.database.exists());

    let legacy = Connection::open(&paths.database).unwrap();
    legacy.pragma_update(None, "journal_mode", "WAL").unwrap();
    legacy.pragma_update(None, "wal_autocheckpoint", 0).unwrap();
    legacy
        .execute_batch(
            "CREATE TABLE live_marker(value TEXT NOT NULL);
             INSERT INTO live_marker(value) VALUES('checkpointed');
             PRAGMA user_version=29;
             PRAGMA wal_checkpoint(TRUNCATE);
             BEGIN IMMEDIATE;
             UPDATE live_marker SET value='committed-in-wal';
             PRAGMA user_version=15;
             COMMIT;",
        )
        .unwrap();
    let main_bytes = std::fs::read(&paths.database).unwrap();
    assert_eq!(
        u32::from_be_bytes(main_bytes[60..64].try_into().unwrap()),
        29
    );
    assert!(
        std::fs::metadata(format!("{}-wal", paths.database.display()))
            .unwrap()
            .len()
            > 0
    );
    let unsupported = database::check(&paths).unwrap_err().to_string();
    assert!(unsupported.contains("unsupported database schema version 15"));
    assert_eq!(
        legacy
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i64>(0))
            .unwrap(),
        15
    );
    assert_eq!(
        legacy
            .query_row("SELECT value FROM live_marker", [], |row| {
                row.get::<_, String>(0)
            })
            .unwrap(),
        "committed-in-wal"
    );

    let source = m4a_paths("readonly-restore-source");
    Store::open(&source.database).unwrap();
    let backup = m4a_backup_path(&database::backup(&source, None).unwrap());
    let live_family = [
        paths.database.clone(),
        PathBuf::from(format!("{}-wal", paths.database.display())),
        PathBuf::from(format!("{}-shm", paths.database.display())),
    ];
    let before = live_family
        .iter()
        .map(|path| {
            let metadata = std::fs::metadata(path).unwrap();
            (metadata.dev(), metadata.ino(), std::fs::read(path).unwrap())
        })
        .collect::<Vec<_>>();

    let refusal = database::restore(&paths, &backup).unwrap_err().to_string();

    assert!(refusal.contains("unsupported database schema version 15"));
    assert!(refusal.contains("restore will not migrate or replace"));
    assert!(!paths.state.join("database-restore-journal.json").exists());
    assert!(!paths.state.join("database-quarantine").exists());
    for (index, path) in live_family.iter().enumerate() {
        let metadata = std::fs::metadata(path).unwrap();
        assert_eq!(metadata.dev(), before[index].0);
        assert_eq!(metadata.ino(), before[index].1);
        if index != 2 {
            assert_eq!(std::fs::read(path).unwrap(), before[index].2);
        }
    }
    assert_eq!(
        legacy
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i64>(0))
            .unwrap(),
        15
    );
    assert_eq!(
        legacy
            .query_row("SELECT value FROM live_marker", [], |row| {
                row.get::<_, String>(0)
            })
            .unwrap(),
        "committed-in-wal"
    );
}

#[test]
fn m4a_readable_inventory_failure_aborts_before_displacement() {
    let source = m4a_paths("capture-source");
    Store::open(&source.database).unwrap();
    let backup = m4a_backup_path(&database::backup(&source, None).unwrap());
    let target = m4a_paths("capture-target");
    Store::open(&target.database).unwrap();
    let connection = Connection::open(&target.database).unwrap();
    connection
        .pragma_update(None, "foreign_keys", "OFF")
        .unwrap();
    connection.execute_batch("DROP TABLE sessions").unwrap();
    drop(connection);
    let before = std::fs::read(&target.database).unwrap();

    let error = database::restore(&target, &backup).unwrap_err().to_string();

    assert!(error.contains("capture inventory from readable displaced database"));
    assert_eq!(std::fs::read(&target.database).unwrap(), before);
    assert!(!target.state.join("database-restore-journal.json").exists());
    assert!(!target.state.join("database-quarantine").exists());
}

#[test]
fn m4a_restore_rejects_symlinked_live_database_before_journaling() {
    let source = m4a_paths("live-link-source");
    Store::open(&source.database).unwrap();
    let backup = m4a_backup_path(&database::backup(&source, None).unwrap());
    let target = m4a_paths("live-link-target");
    let outside = target.root.with_extension("outside.sqlite3");
    std::fs::copy(&source.database, &outside).unwrap();
    std::os::unix::fs::symlink(&outside, &target.database).unwrap();

    let error = database::restore(&target, &backup).unwrap_err().to_string();

    assert!(error.contains("live database files must be regular"));
    assert!(std::fs::symlink_metadata(&target.database)
        .unwrap()
        .file_type()
        .is_symlink());
    assert!(!target.state.join("database-restore-journal.json").exists());
}

#[test]
fn m4a_instance_lock_refuses_backup_before_snapshot_writes() {
    let paths = m4a_paths("lock");
    Store::open(&paths.database).unwrap();
    let backup_root = paths.root.with_extension("lock-backups");
    let _lock = database::InstanceLock::acquire(&paths).unwrap();
    let error = database::backup(&paths, Some(&backup_root))
        .unwrap_err()
        .to_string();
    assert!(error.contains("another LLMRelay instance owns"));
    assert!(!backup_root.exists());

    let symlink_paths = m4a_paths("lock-symlink");
    let outside = symlink_paths.state.join("outside-lock");
    std::fs::write(&outside, b"not the stable lock inode").unwrap();
    std::fs::set_permissions(&outside, std::fs::Permissions::from_mode(0o600)).unwrap();
    std::os::unix::fs::symlink(&outside, &symlink_paths.lock_file).unwrap();
    let symlink_error = database::InstanceLock::acquire(&symlink_paths)
        .err()
        .unwrap()
        .to_string();
    assert!(symlink_error.contains("open instance lock"));
}

#[test]
fn m4a_backup_captures_wal_and_rejects_changed_snapshot_bytes() {
    let paths = m4a_paths("backup");
    Store::open(&paths.database).unwrap();
    Connection::open(&paths.database)
        .unwrap()
        .execute_batch(
            "INSERT INTO projects(id,display_name,repository_path,repository_identity,base_revision,queue_paused,created_at,updated_at)
             VALUES('wal-project','WAL project','/tmp','wal-identity','base',1,'2026-01-01T00:00:00Z','2026-01-01T00:00:00Z');",
        )
        .unwrap();
    let result = database::backup(&paths, None).unwrap();
    let snapshot = m4a_backup_path(&result);
    let snapshot_database = snapshot.join("database.sqlite3");
    let snapshot_wal = PathBuf::from(format!("{}-wal", snapshot_database.display()));
    let snapshot_shm = PathBuf::from(format!("{}-shm", snapshot_database.display()));
    assert!(!snapshot_wal.exists() && !snapshot_shm.exists());
    assert!(database::verify(&snapshot).unwrap()["verified"] == true);
    assert!(!snapshot_wal.exists() && !snapshot_shm.exists());
    let snapshot_connection = Connection::open(&snapshot_database).unwrap();
    assert_eq!(
        snapshot_connection
            .query_row(
                "SELECT display_name FROM projects WHERE id='wal-project'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "WAL project"
    );
    drop(snapshot_connection);
    std::fs::OpenOptions::new()
        .append(true)
        .open(&snapshot_database)
        .unwrap()
        .write_all(b"changed")
        .unwrap();
    let changed = database::verify(&snapshot).unwrap_err().to_string();
    assert!(changed.contains("length mismatch") || changed.contains("SHA-256 mismatch"));
}

#[test]
fn m4a_restore_revokes_old_authority_and_persists_execution_hold() {
    let source = Fixture::new("m4a-authority-source");
    seed_attempt(&source, "implementation");
    seed_session_for_provider(
        &source,
        "a",
        "implementer",
        "m4a-generation",
        "m4a-session",
        "running",
        Provider::Codex,
    );
    source.execute(
        "INSERT INTO role_credentials(id,role_generation_id,token_hash,permissions_json,created_at)
         VALUES('m4a-credential','m4a-generation',?1,'[\"report_result\"]','2026-01-01T00:00:00Z')",
        params![auth::hash_secret("m4a-old-token")],
    );
    source.execute_batch(
        "UPDATE attempts SET phase='checks',candidate_hash='m4a-candidate',selected_checks_revision=1 WHERE id='a';
         INSERT INTO trip_verification_checks(id,project_id,config_revision_id,check_key,category,
           command_kind,executable,arguments_json,cwd,timeout_seconds,acceptance_rows_json,
           relevant_inputs_json,invalidation_json,original_text)
         VALUES('m4a-check','p','synthetic-seeded-config','focused','focused','argv',
           '/usr/bin/true','[]','/tmp',60,'[]','[]','[]','fixture check');
         INSERT INTO trip_selected_checks(attempt_id,revision,check_id,required,selected_by_generation_id,created_at)
         VALUES('a',1,'m4a-check',1,'m4a-generation','2026-01-01T00:00:00Z');
         INSERT INTO guidance_messages(id,attempt_id,role_generation_id,body,state,reason,created_at)
         VALUES('m4a-guidance','a','m4a-generation','old pending guidance','delivery_unknown',
           'ambiguous before restore','2026-01-01T00:00:00Z')",
    );
    source.execute(
        "INSERT INTO restart_candidates(session_id,attempt_id,task_id,source,state,reason,requested_by,result_json,created_at,updated_at)
         VALUES('m4a-session','a','t','planned_shutdown','queued_capacity','fixture','human',?1,'2026-01-01T00:00:00Z','2026-01-01T00:00:00Z')",
        params![queued_restart_result_json(
            "restore-batch",
            "m4a-session",
            2,
            4,
            Some("2099-01-01T00:00:00Z")
        )],
    );
    let mut source_paths = m4a_paths("authority-source");
    source_paths.database = source.database.clone();
    source_paths.state = source.root.clone();
    let backup = m4a_backup_path(&database::backup(&source_paths, None).unwrap());

    let target = m4a_paths("authority-target");
    database::restore(&target, &backup).unwrap();
    let restored = Store::open(&target.database).unwrap();
    assert_restart_accounting(
        &target.database,
        "m4a-session",
        "cancelled:restore-batch:terminated:2:4:preserved",
    );
    let denied = restored
        .role_context("m4a-old-token")
        .unwrap_err()
        .to_string();
    assert!(denied.contains("database restore hold"));
    let scheduler_denied = Scheduler::new(restored.clone(), target.artifacts.clone())
        .claim_next()
        .unwrap_err()
        .to_string();
    assert!(scheduler_denied.contains("database restore hold"));
    let restored_fixture = Fixture {
        root: target.root.clone(),
        database: target.database.clone(),
        store: restored.clone(),
        synthetic_bundles: None,
    };
    let exact_command_hash = agenticjira::store::json_hash(&serde_json::json!({
        "kind":"argv","executable":"/usr/bin/true","arguments":"[]","shell":null,"cwd":"/tmp"
    }))
    .unwrap();
    let scope_hash = agenticjira::store::json_hash(&serde_json::json!({
        "attempt_id":"a","candidate_hash":"m4a-candidate","check_id":"m4a-check",
        "selected_revision":1,"cwd":"/tmp"
    }))
    .unwrap();
    for lifetime in ["once", "reusable", "family"] {
        let error = execute_trip(
            &restored_fixture,
            &target,
            &format!("held-check-{lifetime}"),
            &TripHumanAction::AuthorizeCheck {
                attempt_id: "a".into(),
                check_id: "m4a-check".into(),
                selected_revision: 1,
                exact_command_hash: exact_command_hash.clone(),
                scope_hash: scope_hash.clone(),
                decision: "approved".into(),
                lifetime: lifetime.into(),
            },
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("database restore hold"));
    }
    let app = Application::new(
        target.clone(),
        restored.clone(),
        std::env::current_exe().unwrap(),
    )
    .unwrap();
    let downstream_state = || {
        Connection::open(&target.database)
            .unwrap()
            .query_row(
                "SELECT
                   (SELECT COUNT(*) FROM permission_requests) || ':' ||
                   (SELECT COUNT(*) FROM permission_rules) || ':' ||
                   (SELECT COUNT(*) FROM trip_check_authorizations) || ':' ||
                   (SELECT COUNT(*) FROM check_runs) || ':' ||
                   (SELECT state FROM guidance_messages WHERE id='m4a-guidance') || ':' ||
                   (SELECT COUNT(*) FROM operation_receipts)",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap()
    };
    let before_direct_entries = downstream_state();
    let context = RoleContext {
        project_id: "p".into(),
        task_id: "t".into(),
        attempt_id: "a".into(),
        role_generation_id: "m4a-generation".into(),
        session_id: "m4a-session".into(),
        credential_id: "m4a-credential".into(),
        transcript_epoch: "e".into(),
        role: RoleKind::Implementer,
        provider: Provider::Codex,
        configuration_revision: 1,
        lane_id: "default".into(),
        permissions: Vec::new(),
    };
    let permission_error = agenticjira::permissions::begin_request(
        &restored,
        &context,
        &serde_json::json!({"tool_name":"shell","tool_input":{"command":"true"}}),
        "held-boot",
        "held-nonce",
    )
    .unwrap_err()
    .to_string();
    assert!(permission_error.contains("database restore hold"));
    let mut decision_connection = Connection::open(&target.database).unwrap();
    let decision_tx = decision_connection.transaction().unwrap();
    let decision_error = agenticjira::permissions::apply_human_decision(
        &decision_tx,
        "held-decision",
        "missing-request",
        0,
        PermissionDecision::ApproveOnce,
        None,
        "must remain held",
    )
    .unwrap_err()
    .to_string();
    assert!(decision_error.contains("database restore hold"));
    drop(decision_tx);
    for error in [
        app.checks.run_selected("a", "m4a-check").unwrap_err(),
        app.roles.deliver_guidance("m4a-guidance").unwrap_err(),
        app.coordinator_tick().unwrap_err(),
        app.resume_restart_sessions("held-restart", None)
            .unwrap_err(),
        app.resume_validation("m4a-session", "unchanged prompt")
            .unwrap_err(),
        app.resume_role_session("m4a-session", "unchanged prompt")
            .unwrap_err(),
        app.launch_validation(ValidationLaunchRequest {
            operation_id: "held-validation-launch".into(),
            cell: "L01".into(),
            provider: Provider::Codex,
            role: RoleKind::Explorer,
            project_path: PathBuf::from("/tmp"),
            model: "fixture".into(),
            effort: "medium".into(),
            prompt: "must not launch".into(),
        })
        .unwrap_err(),
        app.launch_workflow_validation(WorkflowValidationRequest {
            launch: ValidationLaunchRequest {
                operation_id: "held-workflow-validation-launch".into(),
                cell: "L05".into(),
                provider: Provider::Codex,
                role: RoleKind::Implementer,
                project_path: PathBuf::from("/tmp"),
                model: "fixture".into(),
                effort: "medium".into(),
                prompt: "must not launch".into(),
            },
            task_id: "t".into(),
            attempt_id: Some("a".into()),
        })
        .unwrap_err(),
    ] {
        assert!(error.to_string().contains("database restore hold"));
    }
    assert_eq!(downstream_state(), before_direct_entries);
    let connection = Connection::open(&target.database).unwrap();
    assert_eq!(
        connection
            .query_row(
                "SELECT revoked_at IS NOT NULL FROM role_credentials WHERE id='m4a-credential'",
                [],
                |row| row.get::<_, bool>(0),
            )
            .unwrap(),
        true
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT auto_resume_eligible FROM instance_settings WHERE singleton=1",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
        0
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT (SELECT COUNT(*) FROM trip_check_authorizations) +
                        (SELECT COUNT(*) FROM trip_check_permission_rules)",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
        0
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT state || ':' || reason FROM guidance_messages WHERE id='m4a-guidance'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "abandoned:database restore invalidated ambiguous or in-flight delivery"
    );
    database::recover_interrupted_restore_locked(&target).unwrap();
    assert_eq!(
        Connection::open(&target.database)
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM recovery_records WHERE id='database-restore-hold' AND state='attention_required'",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
        1
    );
}

#[test]
fn m4a_restore_claim_and_freeze_recovery_reaches_paused_release() {
    let source = Fixture::new("m4a-claim-freeze-source");
    seed_attempt(&source, "implementation");
    source.execute_batch(
        "UPDATE projects SET repository_path='/tmp';
         INSERT INTO claims(id,task_id,attempt_id,repository_identity,state,created_at,updated_at)
         VALUES('restore-claim','t','a','restore-identity','reserved','2026-01-01T00:00:00Z','2026-01-01T00:00:00Z');
         INSERT INTO freeze_intents(id,attempt_id,kind,state,created_at,updated_at)
         VALUES('restore-freeze','a','code_review','capturing','2026-01-01T00:00:00Z','2026-01-01T00:00:00Z')",
    );
    let mut source_paths = m4a_paths("claim-freeze-source");
    source_paths.database = source.database.clone();
    source_paths.state = source.root.clone();
    let backup = m4a_backup_path(&database::backup(&source_paths, None).unwrap());
    let target = m4a_paths("claim-freeze-target");
    database::restore(&target, &backup).unwrap();
    let restored = Store::open(&target.database).unwrap();

    let hold = workflow::state(&restored)
        .unwrap()
        .decisions
        .into_iter()
        .find(|decision| decision.subject.recovery_id.as_deref() == Some("database-restore-hold"))
        .unwrap();
    assert_eq!(hold.decision_schema, 1);
    assert!(hold
        .prerequisites
        .iter()
        .any(|item| item.evidence["id"] == "restore-claim"));
    assert!(hold
        .prerequisites
        .iter()
        .any(|item| item.evidence["id"] == "restore-freeze"));
    assert!(hold
        .prerequisites
        .iter()
        .any(|item| item.code == "restore.boot_identity"
            && item.state == agenticjira::domain::DecisionEvidenceState::Unknown));

    for ordinal in 0..2 {
        let version = Connection::open(&target.database)
            .unwrap()
            .query_row("SELECT version FROM tasks WHERE id='t'", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap();
        workflow::execute(
            &restored,
            &HumanCommand::ResolveRecovery {
                operation_id: format!("restore-local-recovery-{ordinal}"),
                task_id: "t".into(),
                attempt_id: "a".into(),
                recovery_id: Connection::open(&target.database).unwrap().query_row("SELECT id FROM recovery_records WHERE attempt_id='a' AND state='attention_required' AND id!='database-restore-hold' ORDER BY id LIMIT 1", [], |row| row.get::<_, String>(0)).unwrap(),
            session_id: None,
                expected_version: version,
                decision: "confirm_quiescent".into(),
                evidence:
                    "exclusive restore recovery verified the local prelaunch and freeze boundaries"
                        .into(),
            },
        )
        .unwrap();
    }
    let connection = Connection::open(&target.database).unwrap();
    assert_eq!(
        connection
            .query_row(
                "SELECT state FROM claims WHERE id='restore-claim'",
                [],
                |row| { row.get::<_, String>(0) }
            )
            .unwrap(),
        "cancelled"
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT state FROM freeze_intents WHERE id='restore-freeze'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "abandoned"
    );
    assert_eq!(
        connection
            .query_row("SELECT status FROM attempts WHERE id='a'", [], |row| {
                row.get::<_, String>(0)
            })
            .unwrap(),
        "held"
    );
    assert_eq!(
        connection
            .query_row("SELECT attention FROM tasks WHERE id='t'", [], |row| {
                row.get::<_, String>(0)
            })
            .unwrap(),
        "paused"
    );
    drop(connection);
    database::release_hold(&target).unwrap();
}

#[test]
fn m4a_restore_session_check_and_claim_recovery_never_resurrects_work() {
    let source = Fixture::new("m4a-process-recovery-source");
    seed_attempt(&source, "checks");
    seed_session(
        &source,
        "a",
        "implementer",
        "restore-generation",
        "restore-session",
        "running",
    );
    let prior_boot = m4a_prior_boot_identity();
    let anchor = serde_json::json!({
        "pid":429496729_u32,
        "process_group_id":429496729,
        "native_start_marker":"prior-restore-process",
        "boot_identity":&prior_boot,
    })
    .to_string();
    source.execute("UPDATE projects SET repository_path='/tmp'", []);
    source.execute(
        "UPDATE sessions SET recovery_root_pid=429496729,recovery_process_group_id=429496729,
           recovery_anchor_json=?1,launch_boot_identity=?2 WHERE id='restore-session'",
        params![&anchor, &prior_boot],
    );
    source.execute(
        "INSERT INTO check_runs(id,attempt_id,candidate_hash,executable,arguments_json,cwd,status,
           evidence_json,created_at,recovery_root_pid,recovery_process_group_id,recovery_anchor_json,
           launch_boot_identity)
         VALUES('restore-check','a','candidate','/usr/bin/true','[]','/tmp','running','{}',
           '2026-01-01T00:00:00Z',429496729,429496729,?1,?2)",
        params![&anchor, &prior_boot],
    );
    source.execute(
        "INSERT INTO claims(id,task_id,attempt_id,repository_identity,state,created_at,updated_at)
         VALUES('restore-process-claim','t','a','restore-process-identity','running',
           '2026-01-01T00:00:00Z','2026-01-01T00:00:00Z')",
        [],
    );
    let mut source_paths = m4a_paths("process-recovery-source");
    source_paths.database = source.database.clone();
    source_paths.state = source.root.clone();
    let backup = m4a_backup_path(&database::backup(&source_paths, None).unwrap());
    let target = m4a_paths("process-recovery-target");
    database::restore(&target, &backup).unwrap();
    let restored = Store::open(&target.database).unwrap();

    let version = |path: &PathBuf| {
        Connection::open(path)
            .unwrap()
            .query_row("SELECT version FROM tasks WHERE id='t'", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap()
    };
    workflow::execute(
        &restored,
        &HumanCommand::ResolveRecovery {
            operation_id: "restore-check-recovery".into(),
            task_id: "t".into(),
            attempt_id: "a".into(),
            recovery_id: Connection::open(&target.database).unwrap().query_row("SELECT id FROM recovery_records WHERE json_extract(detail_json,'$.check_id') IS NOT NULL AND state='attention_required' LIMIT 1", [], |row| row.get::<_, String>(0)).unwrap(),
            session_id: None,
            expected_version: version(&target.database),
            decision: "confirm_quiescent".into(),
            evidence: "prior-boot check ownership is absent".into(),
        },
    )
    .unwrap();
    workflow::execute(
        &restored,
        &HumanCommand::ResolveRecovery {
            operation_id: "restore-session-recovery".into(),
            task_id: "t".into(),
            attempt_id: "a".into(),
            recovery_id: Connection::open(&target.database).unwrap().query_row("SELECT id FROM recovery_records WHERE session_id='restore-session' AND state='attention_required' LIMIT 1", [], |row| row.get::<_, String>(0)).unwrap(),
            session_id: Some("restore-session".into()),
            expected_version: version(&target.database),
            decision: "confirm_quiescent".into(),
            evidence: "prior-boot session ownership is absent".into(),
        },
    )
    .unwrap();
    let connection = Connection::open(&target.database).unwrap();
    assert_eq!(
        connection
            .query_row(
                "SELECT status FROM check_runs WHERE id='restore-check'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "reconciled_interrupted"
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT state FROM claims WHERE id='restore-process-claim'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "cancelled"
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT status || ':' || attention FROM attempts JOIN tasks ON tasks.id=attempts.task_id WHERE attempts.id='a'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "held:paused"
    );
    drop(connection);
    database::release_hold(&target).unwrap();
}

#[test]
fn m4a_unreadable_displaced_database_requires_changed_boot_for_release() {
    let source = m4a_paths("release-source");
    Store::open(&source.database).unwrap();
    let backup = m4a_backup_path(&database::backup(&source, None).unwrap());
    let target = m4a_paths("release-target");
    std::fs::write(&target.database, b"not a SQLite database").unwrap();
    database::restore(&target, &backup).unwrap();

    let same_boot = database::release_hold(&target).unwrap_err().to_string();
    assert!(same_boot.contains("requires a verified OS reboot"));
    let journal_path = target.state.join("database-restore-journal.json");
    let mut journal: serde_json::Value =
        serde_json::from_slice(&std::fs::read(&journal_path).unwrap()).unwrap();
    let current = agenticjira::supervisor::system_boot_identity().unwrap();
    let replacement = uuid::Uuid::new_v4().to_string();
    journal["inventory"]["recorded_boot"] =
        serde_json::Value::String(if current.starts_with("linux:") {
            format!("linux:{replacement}")
        } else {
            format!("darwin:bootsessionuuid:{replacement}")
        });
    std::fs::write(&journal_path, serde_json::to_vec_pretty(&journal).unwrap()).unwrap();
    let released = database::release_hold(&target).unwrap();
    assert_eq!(released["restore_hold"], false);
    assert_eq!(released["automatic_resume"], false);
    let connection = Connection::open(&target.database).unwrap();
    assert_eq!(
        connection
            .query_row(
                "SELECT state FROM recovery_records WHERE id='database-restore-hold'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "resolved_quiescent"
    );
    database::recover_interrupted_restore_locked(&target).unwrap();
    assert_eq!(
        Connection::open(&target.database)
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM recovery_records WHERE id='database-restore-hold' AND state='attention_required'",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
        0
    );
}

#[test]
fn m4a_repeated_restore_supersedes_snapshot_holds_and_remains_releasable() {
    let source = m4a_paths("repeat-source");
    Store::open(&source.database).unwrap();
    let original = m4a_backup_path(&database::backup(&source, None).unwrap());
    let target = m4a_paths("repeat-target");

    database::restore(&target, &original).unwrap();
    let during_hold = m4a_backup_path(&database::backup(&target, None).unwrap());
    database::release_hold(&target).unwrap();
    let after_release = m4a_backup_path(&database::backup(&target, None).unwrap());

    let first_repeat = database::restore(&target, &after_release).unwrap();
    let first_operation = first_repeat["operation_id"].as_str().unwrap().to_owned();
    let connection = Connection::open(&target.database).unwrap();
    assert_eq!(
        connection
            .query_row(
                "SELECT json_extract(detail_json,'$.operation_id') FROM recovery_records
                 WHERE id='database-restore-hold' AND state='attention_required'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        first_operation
    );
    drop(connection);
    database::release_hold(&target).unwrap();

    let second_repeat = database::restore(&target, &during_hold).unwrap();
    assert_ne!(second_repeat["operation_id"], first_repeat["operation_id"]);
    database::release_hold(&target).unwrap();
    assert_eq!(
        Connection::open(&target.database)
            .unwrap()
            .query_row(
                "SELECT state FROM recovery_records WHERE id='database-restore-hold'",
                [],
                |row| row.get::<_, String>(0),
            )
            .unwrap(),
        "resolved_quiescent"
    );
}

#[test]
fn m4a_restore_journal_boundaries_recover_or_refuse_exactly() {
    let source = m4a_paths("journal-source");
    Store::open(&source.database).unwrap();
    let backup = m4a_backup_path(&database::backup(&source, None).unwrap());
    let verified_target = m4a_paths("journal-verified");
    Store::open(&verified_target.database).unwrap();
    database::restore(&verified_target, &backup).unwrap();
    let mut verified = m4a_read_journal(&verified_target);
    m4a_recreate_verified_boundary(&verified_target, &mut verified);
    let refusal = database::recover_interrupted_restore_locked(&verified_target)
        .unwrap_err()
        .to_string();
    assert!(refusal.contains("stopped before displacement"));
    let resumed = database::restore(&verified_target, &backup).unwrap();
    assert_eq!(resumed["operation_id"], verified["operation_id"]);
    m4a_assert_recovered_restore(&verified_target, &verified);

    let displacing_target = m4a_paths("journal-displacing");
    Store::open(&displacing_target.database).unwrap();
    database::restore(&displacing_target, &backup).unwrap();
    let mut displacing = m4a_read_journal(&displacing_target);
    m4a_recreate_verified_boundary(&displacing_target, &mut displacing);
    let first = &mut displacing["moves"].as_array_mut().unwrap()[0];
    std::fs::rename(
        PathBuf::from(first["source"].as_str().unwrap()),
        PathBuf::from(first["quarantine"].as_str().unwrap()),
    )
    .unwrap();
    displacing["phase"] = serde_json::Value::String("displacing".into());
    m4a_write_journal(&displacing_target, &displacing);
    database::recover_interrupted_restore_locked(&displacing_target).unwrap();
    m4a_assert_recovered_restore(&displacing_target, &displacing);

    let installing_target = m4a_paths("journal-installing");
    Store::open(&installing_target.database).unwrap();
    database::restore(&installing_target, &backup).unwrap();
    let mut installing = m4a_read_journal(&installing_target);
    m4a_prepare_installing_boundary(&installing_target, &mut installing);
    database::recover_interrupted_restore_locked(&installing_target).unwrap();
    m4a_assert_recovered_restore(&installing_target, &installing);

    for hold_exists in [false, true] {
        let target = m4a_paths(if hold_exists {
            "journal-post-hold"
        } else {
            "journal-pre-hold"
        });
        database::restore(&target, &backup).unwrap();
        let mut journal = m4a_read_journal(&target);
        if !hold_exists {
            m4a_prepare_hold_pending_boundary(&target, &mut journal);
        } else {
            let live_hash = sha256(&std::fs::read(&target.database).unwrap());
            let sidecar_exists = journal["moves"].as_array().unwrap()[1..]
                .iter()
                .any(|item| PathBuf::from(item["source"].as_str().unwrap()).exists());
            assert!(
                live_hash != journal["staged_binding"]["sha256"].as_str().unwrap()
                    || sidecar_exists,
                "completed hold did not leave committed database evidence"
            );
        }
        journal["phase"] = serde_json::Value::String("hold_pending".into());
        m4a_write_journal(&target, &journal);
        database::recover_interrupted_restore_locked(&target).unwrap();
        m4a_assert_recovered_restore(&target, &journal);
        assert_eq!(
            Connection::open(&target.database)
                .unwrap()
                .query_row(
                    "SELECT COUNT(*) FROM recovery_records WHERE id='database-restore-hold' AND state='attention_required'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1
        );
    }

    let altered_quarantine_target = m4a_paths("journal-displacing-altered-quarantine");
    Store::open(&altered_quarantine_target.database).unwrap();
    database::restore(&altered_quarantine_target, &backup).unwrap();
    let mut altered_quarantine = m4a_read_journal(&altered_quarantine_target);
    m4a_recreate_verified_boundary(&altered_quarantine_target, &mut altered_quarantine);
    let first = &mut altered_quarantine["moves"].as_array_mut().unwrap()[0];
    let first_source = PathBuf::from(first["source"].as_str().unwrap());
    let first_quarantine = PathBuf::from(first["quarantine"].as_str().unwrap());
    std::fs::rename(first_source, &first_quarantine).unwrap();
    first["disposition"] = serde_json::Value::String("moved".into());
    altered_quarantine["phase"] = serde_json::Value::String("displacing".into());
    m4a_write_journal(&altered_quarantine_target, &altered_quarantine);
    std::fs::OpenOptions::new()
        .append(true)
        .open(first_quarantine)
        .unwrap()
        .write_all(b"altered quarantine evidence")
        .unwrap();
    m4a_assert_recovery_refusal_preserves_files(
        &altered_quarantine_target,
        &altered_quarantine,
        "recorded binding",
    );

    let reappeared_sidecar_target = m4a_paths("journal-installing-reappeared-sidecar");
    Store::open(&reappeared_sidecar_target.database).unwrap();
    database::restore(&reappeared_sidecar_target, &backup).unwrap();
    let mut reappeared_sidecar = m4a_read_journal(&reappeared_sidecar_target);
    m4a_prepare_installing_boundary(&reappeared_sidecar_target, &mut reappeared_sidecar);
    let live_wal = PathBuf::from(format!(
        "{}-wal",
        reappeared_sidecar_target.database.display()
    ));
    std::fs::write(&live_wal, b"foreign pre-restore WAL").unwrap();
    m4a_assert_recovery_refusal_preserves_files(
        &reappeared_sidecar_target,
        &reappeared_sidecar,
        "reappeared after displacement",
    );

    let changed_pre_hold_target = m4a_paths("journal-hold-pending-changed-bytes");
    Store::open(&changed_pre_hold_target.database).unwrap();
    database::restore(&changed_pre_hold_target, &backup).unwrap();
    let mut changed_pre_hold = m4a_read_journal(&changed_pre_hold_target);
    m4a_prepare_hold_pending_boundary(&changed_pre_hold_target, &mut changed_pre_hold);
    let changed_connection = Connection::open(&changed_pre_hold_target.database).unwrap();
    changed_connection
        .pragma_update(None, "journal_mode", "DELETE")
        .unwrap();
    changed_connection
        .execute(
            "UPDATE instance_settings SET updated_at='changed-before-hold' WHERE singleton=1",
            [],
        )
        .unwrap();
    drop(changed_connection);
    m4a_assert_recovery_refusal_preserves_files(
        &changed_pre_hold_target,
        &changed_pre_hold,
        "lacks a committed hold",
    );

    let replaced_post_hold_target = m4a_paths("journal-hold-pending-replaced-inode");
    database::restore(&replaced_post_hold_target, &backup).unwrap();
    let mut replaced_post_hold = m4a_read_journal(&replaced_post_hold_target);
    replaced_post_hold["phase"] = serde_json::Value::String("hold_pending".into());
    m4a_write_journal(&replaced_post_hold_target, &replaced_post_hold);
    let installed_bytes = std::fs::read(&replaced_post_hold_target.database).unwrap();
    let replacement = replaced_post_hold_target
        .state
        .join("replacement-restore-database.sqlite3");
    std::fs::write(&replacement, installed_bytes).unwrap();
    std::fs::rename(&replacement, &replaced_post_hold_target.database).unwrap();
    m4a_assert_recovery_refusal_preserves_files(
        &replaced_post_hold_target,
        &replaced_post_hold,
        "recorded staged-file identity",
    );

    let changed_target = m4a_paths("journal-live-changed");
    Store::open(&changed_target.database).unwrap();
    database::restore(&changed_target, &backup).unwrap();
    let mut changed = m4a_read_journal(&changed_target);
    m4a_recreate_verified_boundary(&changed_target, &mut changed);
    let staged = PathBuf::from(changed["staged_database"].as_str().unwrap());
    let staged_before_retry = std::fs::read(&staged).unwrap();
    std::fs::OpenOptions::new()
        .append(true)
        .open(&changed_target.database)
        .unwrap()
        .write_all(b"changed after verification")
        .unwrap();
    let changed_live_before_retry = std::fs::read(&changed_target.database).unwrap();
    let changed_error = database::restore(&changed_target, &backup)
        .unwrap_err()
        .to_string();
    assert!(changed_error.contains("live database family changed"));
    assert_eq!(std::fs::read(staged).unwrap(), staged_before_retry);
    assert_eq!(
        std::fs::read(&changed_target.database).unwrap(),
        changed_live_before_retry
    );

    for (label, mutate) in [
        (
            "operation",
            (|journal: &mut serde_json::Value| {
                journal["operation_id"] = serde_json::Value::String("not-an-operation".into());
            }) as fn(&mut serde_json::Value),
        ),
        ("staging", |journal: &mut serde_json::Value| {
            journal["staged_database"] = serde_json::Value::String("/tmp/not-staged-here".into());
        }),
        ("move", |journal: &mut serde_json::Value| {
            journal["moves"][0]["source"] =
                serde_json::Value::String("/tmp/not-the-live-database".into());
        }),
    ] {
        let target = m4a_paths(&format!("journal-tamper-{label}"));
        database::restore(&target, &backup).unwrap();
        let before = std::fs::read(&target.database).unwrap();
        let mut journal = m4a_read_journal(&target);
        mutate(&mut journal);
        m4a_write_journal(&target, &journal);
        assert!(database::recover_interrupted_restore_locked(&target).is_err());
        assert_eq!(std::fs::read(&target.database).unwrap(), before);
    }
}

#[test]
fn m4a_retention_prunes_only_verified_snapshots_and_preserves_other_state() {
    let paths = m4a_paths("retention");
    Store::open(&paths.database).unwrap();
    let quarantine = paths
        .state
        .join("database-quarantine")
        .join("operator-evidence");
    std::fs::create_dir_all(&quarantine).unwrap();
    std::fs::write(quarantine.join("preserved.txt"), b"preserve").unwrap();
    let first = database::backup(&paths, None).unwrap();
    let first_snapshot = m4a_backup_path(&first);
    let backup_root = first_snapshot.parent().unwrap().to_owned();
    let unrelated = backup_root.join("operator-notes.txt");
    std::fs::write(&unrelated, b"unrelated").unwrap();
    let manifest_path = first_snapshot.join("manifest.json");
    let mut manifest: serde_json::Value =
        serde_json::from_slice(&std::fs::read(&manifest_path).unwrap()).unwrap();
    manifest["created_at"] = serde_json::Value::String("2000-01-01T00:00:00Z".into());
    std::fs::write(
        &manifest_path,
        serde_json::to_vec_pretty(&manifest).unwrap(),
    )
    .unwrap();
    let mut newest = PathBuf::new();
    for _ in 0..10 {
        newest = m4a_backup_path(&database::backup(&paths, None).unwrap());
    }
    let snapshot_count = std::fs::read_dir(&backup_root)
        .unwrap()
        .filter_map(Result::ok)
        .filter(|entry| entry.path().join("manifest.json").is_file())
        .count();
    assert_eq!(snapshot_count, 10);
    assert!(!first_snapshot.exists());
    assert!(newest.exists());
    assert!(unrelated.exists());
    assert!(quarantine.join("preserved.txt").exists());
}

struct Fixture {
    root: PathBuf,
    database: PathBuf,
    store: Store,
    synthetic_bundles: Option<agenticjira::provider_compatibility::BundleSet>,
}

impl Fixture {
    fn new(name: &str) -> Self {
        install_synthetic_codex_home();
        let root =
            std::env::temp_dir().join(format!("agenticjira-{name}-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let database = root.join("state.sqlite3");
        let store = Store::open(&database).unwrap();
        Self {
            root,
            database,
            store,
            synthetic_bundles: None,
        }
    }

    fn with_synthetic_claude(mut self) -> Self {
        let codex = include_str!("../resources/provider-compatibility/codex.json");
        let mut claude: serde_json::Value = serde_json::from_str(include_str!(
            "../resources/provider-compatibility/claude.json"
        ))
        .unwrap();
        let codex_pack: serde_json::Value = serde_json::from_str(codex).unwrap();
        let mut selector = codex_pack["selectors"][0].clone();
        selector["predicate_id"] = "synthetic-claude-v1".into();
        selector["exact_version"] = "synthetic-claude-v1".into();
        for contract in selector["contracts"].as_array_mut().unwrap() {
            contract["contract_id"] =
                format!("synthetic-claude-{}", contract["role"].as_str().unwrap()).into();
            contract["native_policy_revision"] =
                providers::claude::NATIVE_SANDBOX_POLICY_REVISION.into();
            contract["launch_revision"] = providers::claude::LAUNCH_CONTRACT_REVISION.into();
            contract["resume_revision"] = providers::claude::RESUME_CONTRACT_REVISION.into();
            contract["hook_revision"] = providers::CLAUDE_HOOK_REVISION.into();
        }
        claude["selectors"] = serde_json::json!([selector]);
        let claude = claude.to_string();
        self.store = self
            .store
            .clone()
            .with_synthetic_compatibility_for_tests(codex, &claude);
        self.synthetic_bundles = Some(
            agenticjira::provider_compatibility::BundleSet::synthetic_for_tests(codex, &claude),
        );
        self
    }

    fn connection(&self) -> Connection {
        Connection::open(&self.database).unwrap()
    }

    fn scalar<T: rusqlite::types::FromSql>(&self, sql: &str) -> T {
        self.connection()
            .query_row(sql, [], |row| row.get(0))
            .unwrap()
    }

    fn assert_scalar<T>(&self, sql: &str, expected: T)
    where
        T: rusqlite::types::FromSql + std::fmt::Debug + PartialEq,
    {
        assert_eq!(self.scalar::<T>(sql), expected);
    }

    fn execute<P: rusqlite::Params>(&self, sql: &str, params: P) {
        self.connection().execute(sql, params).unwrap();
    }

    fn execute_batch(&self, sql: &str) {
        self.connection().execute_batch(sql).unwrap();
    }

    fn reserve_role(&self, context: &RoleLaunchContext, launch: &LaunchConfig) {
        self.store.reserve_role_invocation(context, launch).unwrap();
    }

    fn reserve_error(&self, context: &RoleLaunchContext, launch: &LaunchConfig) -> String {
        self.store
            .reserve_role_invocation(context, launch)
            .unwrap_err()
            .to_string()
    }

    fn finish_role(&self, context: &RoleLaunchContext) {
        self.execute(
            "UPDATE sessions SET status='exited',launch_state='finished',exit_json='{\"process_group_quiescent\":true,\"synthetic_fixture\":true}' WHERE id=?1",
            params![context.session_id],
        );
        self.execute(
            "UPDATE role_generations SET status='exited' WHERE id=?1",
            params![context.role_generation_id],
        );
    }

    fn repository(&self, name: &str) -> PathBuf {
        let path = self.root.join(name);
        std::fs::create_dir(&path).unwrap();
        run(&path, &["init", "-q"]);
        run(&path, &["config", "user.name", "AgenticJira Test Fixture"]);
        run(&path, &["config", "user.email", "fixture@example.invalid"]);
        std::fs::write(
            path.join("fixture.txt"),
            "base
",
        )
        .unwrap();
        run(&path, &["add", "fixture.txt"]);
        run(
            &path,
            &[
                "-c",
                "commit.gpgsign=false",
                "-c",
                "core.hooksPath=/dev/null",
                "commit",
                "-qm",
                "base",
            ],
        );
        assert_eq!(output(&path, &["log", "-1", "--format=%B"]).trim(), "base");
        path
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

fn run(cwd: &std::path::Path, args: &[&str]) {
    assert!(Command::new("git")
        .args(args)
        .current_dir(cwd)
        .status()
        .unwrap()
        .success());
    if args.contains(&"commit") {
        let message = output(cwd, &["log", "-1", "--format=%B"]);
        let normalized = message.to_ascii_lowercase();
        for prohibited in [
            "co-authored-by",
            "generated-by",
            "generated with",
            "claude-session",
            "codex",
            "openai",
            "claude",
            "anthropic",
        ] {
            assert!(
                !normalized.contains(prohibited),
                "fixture commit contains prohibited attribution: {message}"
            );
        }
    }
}

fn output(cwd: &std::path::Path, args: &[&str]) -> String {
    String::from_utf8(
        Command::new("git")
            .args(args)
            .current_dir(cwd)
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap()
}

fn roles() -> serde_json::Value {
    roles_for(Provider::Codex)
}

fn role_override(provider: Provider) -> RoleOverride {
    RoleOverride {
        provider,
        model: match provider {
            Provider::Codex => "gpt-5.6-sol",
            Provider::Claude => "claude-opus-4-1",
        }
        .into(),
        effort: "high".into(),
    }
}

fn roles_for(provider: Provider) -> serde_json::Value {
    let value = serde_json::to_value(role_override(provider)).unwrap();
    serde_json::json!({
        "manager": value,
        "explorer": value,
        "plan_reviewer": value,
        "implementer": value,
        "code_reviewer": value,
        "final_verifier": value,
    })
}

fn sha256(bytes: &[u8]) -> String {
    hex::encode(sha2::Sha256::digest(bytes))
}

fn seed_synthetic_installed_project(
    fixture: &Fixture,
    project_id: &str,
    root: &std::path::Path,
    provider: Provider,
) {
    let package_root =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("resources/trip-explorer/0.12.0");
    let source: serde_json::Value = serde_json::from_str(include_str!(
        "../resources/trip-explorer/0.12.0/source-manifest.json"
    ))
    .unwrap();
    let files = source["files"].as_object().unwrap();
    let state = root.join(".agents/trip-explorer");
    let mut base = serde_json::Map::new();
    let mut bin = serde_json::Map::new();
    for (relative, expected) in files {
        if relative == "references/adaptation-contract.md" {
            continue;
        }
        let bytes = std::fs::read(package_root.join(relative)).unwrap();
        assert_eq!(sha256(&bytes), expected.as_str().unwrap());
        let base_path = state
            .join("base")
            .join(agenticjira::trip::PACKAGE_VERSION)
            .join(relative);
        std::fs::create_dir_all(base_path.parent().unwrap()).unwrap();
        std::fs::write(base_path, &bytes).unwrap();
        if let Some(active) = relative.strip_prefix("skills/") {
            let active = root.join(".agents/skills").join(active);
            std::fs::create_dir_all(active.parent().unwrap()).unwrap();
            std::fs::write(active, &bytes).unwrap();
        } else if let Some(active) = relative.strip_prefix("bin/") {
            let active = state.join("bin").join(active);
            std::fs::create_dir_all(active.parent().unwrap()).unwrap();
            std::fs::write(&active, &bytes).unwrap();
            bin.insert(
                active.file_name().unwrap().to_string_lossy().into_owned(),
                expected.clone(),
            );
        }
        base.insert(relative.clone(), expected.clone());
    }
    let profile = role_override(provider);
    let mut proposal = setup_proposal(&profile);
    if provider == Provider::Claude {
        for profile_name in ["readonly", "writer", "final"] {
            let selected = &mut proposal["profiles"][profile_name];
            selected["adapter"] = serde_json::json!("claude");
            selected["provider"] = serde_json::json!("claude");
            selected["model"] = serde_json::json!(profile.model.clone());
            selected["effort"] = serde_json::json!(profile.effort.clone());
        }
        proposal["adapters"] = serde_json::json!({
            "adapters": {
                "claude": {
                    "provider": "claude",
                    "kind": "native-agent",
                    "capabilities": {
                        "read_only": true,
                        "workspace_write": true,
                        "resume": true,
                        "fresh_session": true
                    }
                }
            }
        });
    }
    let mut config = proposal.clone();
    let adapters = config["adapters"].clone();
    for key in ["host_manager", "adapters", "agents_file", "local_exclude"] {
        config.as_object_mut().unwrap().remove(key);
    }
    std::fs::write(root.join("AGENTS.md"), "# Disposable fixture\n").unwrap();
    let preflight = serde_json::json!([{"synthetic_fixture": true, "native_proof": false}]);
    let config_bytes = serde_json::to_vec_pretty(&config).unwrap();
    let adapters_bytes = serde_json::to_vec_pretty(&adapters).unwrap();
    let preflight_bytes = serde_json::to_vec_pretty(&preflight).unwrap();
    std::fs::create_dir_all(&state).unwrap();
    for (name, bytes) in [
        ("config.json", &config_bytes),
        ("adapters.json", &adapters_bytes),
        ("preflight.json", &preflight_bytes),
    ] {
        std::fs::write(state.join(name), bytes).unwrap();
    }
    let manifest = serde_json::json!({
        "version": agenticjira::trip::PACKAGE_VERSION,
        "installed_at": "2026-01-01T00:00:00Z",
        "base": base,
        "bin": bin,
        "config_sha256": sha256(&config_bytes),
        "adapters_sha256": sha256(&adapters_bytes),
        "preflight_sha256": sha256(&preflight_bytes),
        "llmrelay": {
            "workflow_id": agenticjira::trip::WORKFLOW_ID,
            "upstream_source_hash": agenticjira::trip::source_hash(),
            "overlay_hash": agenticjira::trip::overlay_hash(),
        }
    });
    let manifest_bytes = serde_json::to_vec_pretty(&manifest).unwrap();
    std::fs::write(state.join("manifest.json"), &manifest_bytes).unwrap();

    let revision = format!("synthetic-trip-{project_id}");
    let setup_id = format!("synthetic-setup-{project_id}");
    let runtime_fixture_id = format!("synthetic-runtime-fixture-{project_id}");
    let runtime_fixture_root = fixture.root.join(&runtime_fixture_id);
    std::fs::create_dir(&runtime_fixture_root).unwrap();
    run(&runtime_fixture_root, &["init", "-q"]);
    run(
        &runtime_fixture_root,
        &[
            "-c",
            "user.name=AgenticJira Test Fixture",
            "-c",
            "user.email=fixture@example.invalid",
            "-c",
            "commit.gpgsign=false",
            "-c",
            "core.hooksPath=/dev/null",
            "commit",
            "--allow-empty",
            "-qm",
            "base",
        ],
    );
    let runtime_fixture_head = output(&runtime_fixture_root, &["rev-parse", "HEAD"])
        .trim()
        .to_owned();
    let runtime_fixture_identity = agenticjira::workspace::inspect(&runtime_fixture_root)
        .unwrap()
        .identity;
    let settings =
        serde_json::json!({"roles": roles_for(provider), "trip_config_revision_id": revision});
    let connection = fixture.connection();
    connection.execute(
        "INSERT INTO projects(id,display_name,repository_path,repository_identity,base_revision,queue_paused,created_at,updated_at,internal_purpose)
         VALUES(?1,'Synthetic runtime fixture',?2,?3,?4,1,'2026-01-01T00:00:00Z','2026-01-01T00:00:00Z','trip_setup_fixture')",
        params![runtime_fixture_id,runtime_fixture_root.to_string_lossy(),runtime_fixture_identity,runtime_fixture_head],
    ).unwrap();
    connection.execute(
        "INSERT INTO trip_setup_operations(id,project_id,fixture_project_id,state,target_inventory_json,proposal_json,created_at,updated_at)
         VALUES(?1,?2,?3,'activated','{}',?4,'2026-01-01T00:00:00Z','2026-01-01T00:00:00Z')",
        params![setup_id,project_id,runtime_fixture_id,proposal.to_string()],
    ).unwrap();
    connection.execute(
        "INSERT INTO trip_config_revisions(id,project_id,revision,state,config_json,adapters_json,preflight_json,verification_json,source_hash,overlay_hash,configuration_hash,created_at,activated_at)
         VALUES(?1,?2,(SELECT COALESCE(MAX(revision),0)+1 FROM trip_config_revisions WHERE project_id=?2),
           'activated',?3,?4,?5,?6,?7,?8,?9,'2026-01-01T00:00:00Z','2026-01-01T00:00:00Z')",
        params![revision, project_id, config.to_string(), adapters.to_string(), preflight.to_string(), config["verification"].to_string(), agenticjira::trip::source_hash(), agenticjira::trip::overlay_hash(), agenticjira::store::json_hash(&config).unwrap()],
    ).unwrap();
    connection
        .execute(
            "UPDATE projects SET settings_json=?1 WHERE id=?2",
            params![settings.to_string(), project_id],
        )
        .unwrap();
    connection.execute(
        "UPDATE trip_project_state SET readiness='ready',reason='synthetic installed-project fixture',detected_installation='compatible',setup_operation_id=?1,active_config_revision_id=?2,workflow_id=?3,package_version=?4,upstream_source_hash=?5,overlay_hash=?6,manifest_hash=?7,activated_at='2026-01-01T00:00:00Z' WHERE project_id=?8",
        params![setup_id,revision, agenticjira::trip::WORKFLOW_ID, agenticjira::trip::PACKAGE_VERSION, agenticjira::trip::source_hash(), agenticjira::trip::overlay_hash(), sha256(&manifest_bytes), project_id],
    ).unwrap();
}

fn add_project(fixture: &Fixture, path: PathBuf, name: &str) -> String {
    add_project_with_provider(fixture, path, name, Provider::Codex)
}

fn add_project_with_provider(
    fixture: &Fixture,
    path: PathBuf,
    name: &str,
    provider: Provider,
) -> String {
    let installed_root = path.clone();
    let created = workflow::execute(
        &fixture.store,
        &HumanCommand::AddProject {
            operation_id: format!("add-{name}"),
            path,
            display_name: name.into(),
        },
    )
    .unwrap();
    seed_synthetic_installed_project(fixture, &created.entity_id, &installed_root, provider);
    workflow::execute(
        &fixture.store,
        &HumanCommand::SetQueuePaused {
            operation_id: format!("start-{name}"),
            project_id: created.entity_id.clone(),
            expected_version: 1,
            paused: false,
        },
    )
    .unwrap();
    created.entity_id
}

fn create_task(fixture: &Fixture, project: &str, operation: &str, priority: i64) -> String {
    create_task_with_roles(fixture, project, operation, priority, roles())
}

fn create_task_with_manager_provider(
    fixture: &Fixture,
    project: &str,
    operation: &str,
    priority: i64,
) -> String {
    let mut role_overrides = roles();
    role_overrides["manager"] = serde_json::to_value(role_override(Provider::Claude)).unwrap();
    create_task_with_roles(fixture, project, operation, priority, role_overrides)
}

fn create_task_with_roles(
    fixture: &Fixture,
    project: &str,
    operation: &str,
    priority: i64,
    role_overrides: serde_json::Value,
) -> String {
    let mut seeded = std::collections::BTreeSet::new();
    for value in role_overrides
        .as_object()
        .into_iter()
        .flatten()
        .map(|(_, value)| value)
    {
        let config: RoleOverride = serde_json::from_value(value.clone()).unwrap();
        let key = format!("{}:{}:{}", config.provider, config.model, config.effort);
        if seeded.insert(key) {
            seed_supported_capabilities_for_config(fixture, &config);
        }
    }
    workflow::execute_with_runtime(
        &fixture.store,
        &HumanCommand::CreateTask {
            operation_id: operation.into(),
            project_id: project.into(),
            title: operation.into(),
            description: "causal fixture".into(),
            acceptance_criteria: vec!["evidence retained".into()],
            priority,
            ready: true,
            role_overrides,
        },
        Some(&capability_runtime(fixture)),
    )
    .unwrap()
    .entity_id
}

fn seed_supported_capabilities(fixture: &Fixture) {
    seed_supported_capabilities_for(fixture, Provider::Codex)
}

fn seed_supported_capabilities_for(fixture: &Fixture, provider: Provider) {
    seed_supported_capabilities_for_config(fixture, &role_override(provider));
}

fn seed_supported_capabilities_for_config(fixture: &Fixture, config: &RoleOverride) {
    seed_supported_capabilities_for_config_with_runtime(
        fixture,
        config,
        &capability_runtime(fixture),
    );
}

fn seed_supported_capabilities_for_config_with_runtime(
    fixture: &Fixture,
    config: &RoleOverride,
    runtime: &agenticjira::trip::CapabilityRuntime,
) {
    let connection = fixture.connection();
    let hooks = &runtime.hooks;
    let executable = &runtime.executable;
    let projects = {
        let mut statement = connection
            .prepare(
                "SELECT p.id,p.repository_path,p.settings_json,p.version,setup.id,
                        s.active_config_revision_id,r.configuration_hash,r.config_json,r.adapters_json,
                        fixture.id,fixture.repository_path,fixture.repository_identity
                 FROM projects p JOIN trip_project_state s ON s.project_id=p.id
                 JOIN trip_config_revisions r ON r.id=s.active_config_revision_id
                 JOIN trip_setup_operations selected ON selected.id=s.setup_operation_id
                 JOIN trip_setup_operations setup ON setup.id=CASE WHEN selected.state='activated' THEN selected.id ELSE selected.supersedes_setup_operation_id END
                 JOIN projects fixture ON fixture.id=setup.fixture_project_id
                 WHERE p.internal_purpose IS NULL AND s.readiness='ready' AND setup.state='activated'",
            )
            .unwrap();
        statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, i64>(3)?,
                    row.get::<_, String>(4)?,
                    row.get::<_, String>(5)?,
                    row.get::<_, String>(6)?,
                    row.get::<_, String>(7)?,
                    row.get::<_, String>(8)?,
                    row.get::<_, String>(9)?,
                    row.get::<_, String>(10)?,
                    row.get::<_, String>(11)?,
                ))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap()
    };
    for (
        project_id,
        repository_path,
        settings_text,
        project_version,
        setup_id,
        config_revision,
        configuration_hash,
        project_config_text,
        adapters_text,
        fixture_project_id,
        fixture_root,
        fixture_identity,
    ) in projects
    {
        let settings: serde_json::Value = serde_json::from_str(&settings_text).unwrap();
        let project_config: serde_json::Value = serde_json::from_str(&project_config_text).unwrap();
        let adapters: serde_json::Value = serde_json::from_str(&adapters_text).unwrap();
        for role in [
            RoleKind::Manager,
            RoleKind::Explorer,
            RoleKind::PlanReviewer,
            RoleKind::Implementer,
            RoleKind::CodeReviewer,
            RoleKind::FinalReviewer,
        ] {
            let role_name = role.to_string();
            let current: RoleOverride =
                serde_json::from_value(settings["roles"][&role_name].clone()).unwrap();
            if serde_json::to_value(&current).unwrap() != serde_json::to_value(config).unwrap() {
                continue;
            }
            let (adapter_name, adapter_definition, configured_profile) = if role
                == RoleKind::Manager
            {
                (
                    "llmrelay_service_native_manager".to_owned(),
                    serde_json::json!({
                        "adapter":"llmrelay_service_native_manager",
                        "revision":"llmrelay-service-native-manager-v1",
                        "definition":{"provider":current.provider,"kind":"native-agent","capabilities":{"read_only":true,"resume":true,"service_selected":true}}
                    }),
                    None,
                )
            } else {
                let required = if role == RoleKind::Implementer {
                    "workspace_write"
                } else {
                    "read_only"
                };
                let session = if role == RoleKind::FinalReviewer {
                    "fresh_session"
                } else {
                    "resume"
                };
                let definitions = adapters["adapters"].as_object().unwrap();
                let configured = project_config["roles"][&role_name]["profile"]
                    .as_str()
                    .and_then(|profile| project_config["profiles"][profile]["adapter"].as_str());
                let configured_profile = project_config["roles"][&role_name]["profile"]
                    .as_str()
                    .map(|profile| project_config["profiles"][profile].clone())
                    .unwrap();
                let eligible = |definition: &serde_json::Value| {
                    definition["provider"] == serde_json::json!(current.provider)
                        && matches!(
                            definition["kind"].as_str(),
                            Some("native-agent" | "builtin-cli")
                        )
                        && definition["capabilities"][required] == true
                        && definition["capabilities"][session] == true
                };
                let selected = configured
                    .filter(|name| definitions.get(*name).is_some_and(&eligible))
                    .map(str::to_owned)
                    .or_else(|| {
                        let matches = definitions
                            .iter()
                            .filter(|(_, definition)| eligible(definition))
                            .collect::<Vec<_>>();
                        (matches.len() == 1).then(|| matches[0].0.clone())
                    })
                    .unwrap();
                (
                    selected.clone(),
                    definitions[&selected].clone(),
                    Some(configured_profile),
                )
            };
            let authority = if role == RoleKind::Implementer {
                "workspace-write"
            } else {
                "read-only"
            };
            let session = if role == RoleKind::FinalReviewer {
                "fresh"
            } else {
                "retained"
            };
            let profile = configured_profile.unwrap_or_else(|| {
                serde_json::json!({"adapter":adapter_name,"provider":current.provider,"model":current.model,"effort":current.effort,"authority":authority,"session":session})
            });
            let launch = providers::prepare_role_launch_with_bundles(
                current.provider,
                role,
                &current.model,
                &current.effort,
                PathBuf::from(&repository_path).as_path(),
                "capability admission only",
                &runtime.role_socket,
                "normalized-admission-token",
                "normalized-admission-generation",
                "normalized-admission-session",
                None,
                hooks,
                executable,
                fixture
                    .synthetic_bundles
                    .as_ref()
                    .unwrap_or(&agenticjira::provider_compatibility::BundleSet::embedded()),
            )
            .unwrap();
            let key = providers::capability_key(&launch.config).unwrap();
            let identity = providers::capability_identity(&launch.config).unwrap();
            let scope = serde_json::json!({
                "project_id":project_id,"task_id":null,"entity_version":project_version,
                "setup_operation_id":setup_id,"fixture_project_id":fixture_project_id,
                "fixture_repository_identity":fixture_identity,"fixture_root_hash":sha256(fixture_root.as_bytes()),
                "scope_hash":"synthetic-current-project-scope",
                "profiles":[{"role":role,"settings_revision":null,"source":"project_default",
                    "profile_hash":agenticjira::store::json_hash(&profile).unwrap(),
                    "project_config_revision_id":config_revision,"project_configuration_hash":configuration_hash,
                    "adapter":adapter_name,"adapter_hash":if role == RoleKind::Manager {
                        agenticjira::store::json_hash(&adapter_definition).unwrap()
                    } else {
                        agenticjira::store::json_hash(&serde_json::json!({"adapter":adapter_name,"definition":adapter_definition})).unwrap()
                    },
                    "capability_key":key,"capability_identity":serde_json::to_string(&identity).unwrap()}]
            });
            let mut scopes = connection
                .query_row(
                    "SELECT proof_json FROM capabilities WHERE provider=?1 AND executable_version=?2 AND role=?3 AND mode='interactive_pty' AND config_hash=?4",
                    params![launch.config.provider.to_string(),launch.config.executable_version,role_name,key],
                    |row| row.get::<_,String>(0),
                )
                .optional()
                .unwrap()
                .and_then(|proof| serde_json::from_str::<serde_json::Value>(&proof).ok())
                .and_then(|proof| proof["runtime_scopes"].as_array().cloned())
                .unwrap_or_default();
            if !scopes.contains(&scope) {
                scopes.push(scope.clone());
            }
            let proof = serde_json::json!({
                "fixture": true,
                "runtime_scope": scope,
                "runtime_scopes": scopes,
                "compatibility": identity.compatibility,
                "model": current.model,
                "effort": current.effort,
            });
            connection.execute(
                "INSERT INTO capabilities(id,provider,executable_version,role,mode,config_hash,status,evidence_reference,gaps_json,checked_at,proof_json)
                 VALUES(?1,?2,?3,?4,'interactive_pty',?5,'supported','fixture','[]','2026-01-01T00:00:00Z',?6)
                 ON CONFLICT(provider,executable_version,role,mode,config_hash) DO UPDATE SET
                   status='supported',evidence_reference='fixture',gaps_json='[]',checked_at='2026-01-01T00:00:00Z',proof_json=excluded.proof_json",
                params![uuid::Uuid::new_v4().to_string(), launch.config.provider.to_string(), launch.config.executable_version, role_name, key, proof.to_string()],
            ).unwrap();
        }
    }
    let overrides = {
        let mut statement = connection.prepare(
            "SELECT t.id,t.version,p.id,p.repository_path,p.settings_json,rs.role,rs.revision,rs.config_json,
                    setup.id,fixture.id,fixture.repository_path,fixture.repository_identity,
                    s.active_config_revision_id,r.configuration_hash,r.config_json,r.adapters_json
             FROM role_settings rs JOIN tasks t ON t.id=rs.task_id JOIN projects p ON p.id=t.project_id
             JOIN trip_project_state s ON s.project_id=p.id
             JOIN trip_setup_operations selected ON selected.id=s.setup_operation_id
             JOIN trip_setup_operations setup ON setup.id=CASE WHEN selected.state='activated' THEN selected.id ELSE selected.supersedes_setup_operation_id END
             JOIN projects fixture ON fixture.id=setup.fixture_project_id
             JOIN trip_config_revisions r ON r.id=s.active_config_revision_id
             WHERE rs.revision=(SELECT MAX(latest.revision) FROM role_settings latest WHERE latest.task_id=rs.task_id AND latest.role=rs.role)",
        ).unwrap();
        statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, i64>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, String>(4)?,
                    row.get::<_, String>(5)?,
                    row.get::<_, i64>(6)?,
                    row.get::<_, String>(7)?,
                    row.get::<_, String>(8)?,
                    row.get::<_, String>(9)?,
                    row.get::<_, String>(10)?,
                    row.get::<_, String>(11)?,
                    row.get::<_, String>(12)?,
                    row.get::<_, String>(13)?,
                    row.get::<_, String>(14)?,
                    row.get::<_, String>(15)?,
                ))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap()
    };
    for (
        task_id,
        task_version,
        project_id,
        repository_path,
        settings_text,
        role_name,
        revision,
        config_text,
        setup_id,
        fixture_project_id,
        fixture_root,
        fixture_identity,
        config_revision,
        configuration_hash,
        project_config_text,
        adapters_text,
    ) in overrides
    {
        let requested: RoleOverride = serde_json::from_str(&config_text).unwrap();
        if serde_json::to_value(&requested).unwrap() != serde_json::to_value(config).unwrap() {
            continue;
        }
        let project_settings: serde_json::Value = serde_json::from_str(&settings_text).unwrap();
        if project_settings["roles"][&role_name] == serde_json::to_value(&requested).unwrap() {
            continue;
        }
        let role: RoleKind = role_name.parse().unwrap();
        let project_config: serde_json::Value = serde_json::from_str(&project_config_text).unwrap();
        let adapters: serde_json::Value = serde_json::from_str(&adapters_text).unwrap();
        let (adapter_name, adapter_definition) = if role == RoleKind::Manager {
            (
                "llmrelay_service_native_manager".to_owned(),
                serde_json::json!({"adapter":"llmrelay_service_native_manager","revision":"llmrelay-service-native-manager-v1","definition":{"provider":requested.provider,"kind":"native-agent","capabilities":{"read_only":true,"resume":true,"service_selected":true}}}),
            )
        } else {
            let required = if role == RoleKind::Implementer {
                "workspace_write"
            } else {
                "read_only"
            };
            let session = if role == RoleKind::FinalReviewer {
                "fresh_session"
            } else {
                "resume"
            };
            let definitions = adapters["adapters"].as_object().unwrap();
            let configured = project_config["roles"][&role_name]["profile"]
                .as_str()
                .and_then(|profile| project_config["profiles"][profile]["adapter"].as_str());
            let eligible = |definition: &serde_json::Value| {
                definition["provider"] == serde_json::json!(requested.provider)
                    && matches!(
                        definition["kind"].as_str(),
                        Some("native-agent" | "builtin-cli")
                    )
                    && definition["capabilities"][required] == true
                    && definition["capabilities"][session] == true
            };
            let selected = configured
                .filter(|name| definitions.get(*name).is_some_and(&eligible))
                .map(str::to_owned)
                .or_else(|| {
                    let candidates = definitions
                        .iter()
                        .filter(|(_, definition)| eligible(definition))
                        .collect::<Vec<_>>();
                    (candidates.len() == 1).then(|| candidates[0].0.clone())
                })
                .unwrap();
            (selected.clone(), definitions[&selected].clone())
        };
        let authority = if role == RoleKind::Implementer {
            "workspace-write"
        } else {
            "read-only"
        };
        let session = if role == RoleKind::FinalReviewer {
            "fresh"
        } else {
            "retained"
        };
        let profile = serde_json::json!({"adapter":adapter_name,"provider":requested.provider,"model":requested.model,"effort":requested.effort,"authority":authority,"session":session});
        let launch = providers::prepare_role_launch_with_bundles(
            requested.provider,
            role,
            &requested.model,
            &requested.effort,
            PathBuf::from(&repository_path).as_path(),
            "capability admission only",
            &runtime.role_socket,
            "normalized-admission-token",
            "normalized-admission-generation",
            "normalized-admission-session",
            None,
            hooks,
            executable,
            fixture
                .synthetic_bundles
                .as_ref()
                .unwrap_or(&agenticjira::provider_compatibility::BundleSet::embedded()),
        )
        .unwrap_or_else(|error| {
            panic!(
                "fixture capability preparation {project_id} {role_name} {:?}: {error:#}",
                requested.provider
            )
        });
        let key = providers::capability_key(&launch.config).unwrap();
        let identity = providers::capability_identity(&launch.config).unwrap();
        let adapter_hash = if role == RoleKind::Manager {
            agenticjira::store::json_hash(&adapter_definition).unwrap()
        } else {
            agenticjira::store::json_hash(
                &serde_json::json!({"adapter":adapter_name,"definition":adapter_definition}),
            )
            .unwrap()
        };
        let scope = serde_json::json!({"project_id":project_id,"task_id":task_id,"entity_version":task_version,"setup_operation_id":setup_id,"fixture_project_id":fixture_project_id,"fixture_repository_identity":fixture_identity,"fixture_root_hash":sha256(fixture_root.as_bytes()),"scope_hash":"synthetic-current-task-scope","profiles":[{"role":role,"settings_revision":revision,"source":"task_override","profile_hash":agenticjira::store::json_hash(&profile).unwrap(),"project_config_revision_id":config_revision,"project_configuration_hash":configuration_hash,"adapter":adapter_name,"adapter_hash":adapter_hash,"capability_key":key,"capability_identity":serde_json::to_string(&identity).unwrap()}]});
        let mut scopes=connection.query_row("SELECT proof_json FROM capabilities WHERE provider=?1 AND executable_version=?2 AND role=?3 AND mode='interactive_pty' AND config_hash=?4",params![launch.config.provider.to_string(),launch.config.executable_version,role_name,key],|row|row.get::<_,String>(0)).optional().unwrap().and_then(|proof|serde_json::from_str::<serde_json::Value>(&proof).ok()).and_then(|proof|proof["runtime_scopes"].as_array().cloned()).unwrap_or_default();
        if !scopes.contains(&scope) {
            scopes.push(scope.clone());
        }
        let proof = serde_json::json!({
            "fixture": true,
            "runtime_scope": scope,
            "runtime_scopes": scopes,
            "compatibility": identity.compatibility,
            "model": requested.model,
            "effort": requested.effort,
        });
        connection.execute("INSERT INTO capabilities(id,provider,executable_version,role,mode,config_hash,status,evidence_reference,gaps_json,checked_at,proof_json) VALUES(?1,?2,?3,?4,'interactive_pty',?5,'supported','fixture','[]','2026-01-01T00:00:00Z',?6) ON CONFLICT(provider,executable_version,role,mode,config_hash) DO UPDATE SET status='supported',evidence_reference='fixture',gaps_json='[]',checked_at='2026-01-01T00:00:00Z',proof_json=excluded.proof_json",params![uuid::Uuid::new_v4().to_string(),launch.config.provider.to_string(),launch.config.executable_version,role_name,key,proof.to_string()]).unwrap();
    }
}

fn setup_proposal(manager: &RoleOverride) -> serde_json::Value {
    let readonly = serde_json::json!({
        "adapter": "codex", "provider": "codex", "model": "gpt-5.6-sol",
        "effort": "high", "service_tier": null,
        "authority": "read-only", "session": "retained"
    });
    let mut final_profile = readonly.clone();
    final_profile["session"] = serde_json::json!("fresh");
    serde_json::json!({
        "project_name": "Disposable setup fixture",
        "host_manager": manager,
        "guidance": ["AGENTS.md"],
        "documentation": {"no_change_text": "No documentation change"},
        "verification": {"focused": [], "broad": [], "cleanup": []},
        "testing": {"coverage": "minimal"},
        "observability": {"cmux": "off"},
        "roles": {
            "explorer": {"profile": "readonly"},
            "plan_reviewer": {"profile": "readonly"},
            "implementer": {"profile": "writer"},
            "code_reviewer": {"profile": "readonly"},
            "final_verifier": {"profile": "final"}
        },
        "profiles": {
            "readonly": readonly,
            "writer": {
                "adapter": "codex", "provider": "codex", "model": "gpt-5.6-sol",
                "effort": "high", "service_tier": null,
                "authority": "workspace-write", "session": "retained"
            },
            "final": final_profile
        },
        "adapters": {"adapters": {"codex": {
            "provider": "codex", "kind": "native-agent",
            "capabilities": {"read_only": true, "workspace_write": true, "resume": true, "fresh_session": true}
        }}},
        "agents_file": {"relative_path": "AGENTS.md", "approved_content": "# Disposable fixture\n"},
        "local_exclude": {"pattern": "/.local/trip-explorer/", "approved": true}
    })
}

fn test_hooks(fixture: &Fixture) -> HookAssets {
    let paths = instance_paths(fixture);
    providers::install_hook_assets(&paths, &std::env::current_exe().unwrap()).unwrap()
}

fn capability_runtime(fixture: &Fixture) -> agenticjira::trip::CapabilityRuntime {
    agenticjira::trip::CapabilityRuntime::from_store(
        &fixture.store,
        test_hooks(fixture),
        fixture.root.join("role.sock"),
        std::env::current_exe().unwrap(),
    )
}

fn capability_runtime_for_paths(
    fixture: &Fixture,
    paths: &InstancePaths,
) -> agenticjira::trip::CapabilityRuntime {
    agenticjira::trip::CapabilityRuntime::from_store(
        &fixture.store,
        test_hooks(fixture),
        paths.role_socket.clone(),
        std::env::current_exe().unwrap(),
    )
}

fn readonly_runtime_outcomes(workspace: &str, nonce: &str, control: &str) -> serde_json::Value {
    let quote = |value: &str| format!("'{}'", value.replace('\'', "'\\''"));
    let command = |operation_id: &str, command: String| {
        serde_json::json!({
            "operation_id":operation_id,"command":command,"attempted":true,"exit_status":1,
            "result":"denied","denial_source":"os","authentication_source":"native_session"
        })
    };
    let direct = format!("{workspace}/runtime-direct-{nonce}.txt");
    let compound = format!("{workspace}/runtime-compound-{nonce}.txt");
    let redirect = format!("{workspace}/runtime-redirect-{nonce}.txt");
    serde_json::json!([
        command(
            "direct_write",
            format!("/usr/bin/touch -- {}", quote(&direct))
        ),
        command(
            "compound_write",
            format!(
                "/bin/sh -lc {}",
                quote(&format!(
                    "/usr/bin/true ; /usr/bin/touch -- {}",
                    quote(&compound)
                ))
            )
        ),
        command(
            "redirect_write",
            format!(
                "/bin/sh -lc {}",
                quote(&format!("/usr/bin/printf x > {}", quote(&redirect)))
            )
        ),
        command(
            "human_control_read",
            format!("/bin/test -r {}", quote(control))
        )
    ])
}

fn implementer_runtime_outcomes(
    provider: Provider,
    workspace: &str,
    fixture_root: &str,
    service_sentinel: &str,
    nonce: &str,
    control: &str,
) -> serde_json::Value {
    let quote = |value: &str| format!("'{}'", value.replace('\'', "'\\''"));
    let command = |operation_id: &str,
                   command: String,
                   result: &str,
                   denial_source: &str,
                   exit_status: Option<i64>| {
        serde_json::json!({
            "operation_id":operation_id,"command":command,
            "attempted":true,"exit_status":exit_status,"result":result,
            "denial_source":denial_source,"authentication_source":"native_session"
        })
    };
    let write = format!("runtime-write-{nonce}.txt");
    let mut outcomes = vec![
        command(
            "workspace_write",
            format!(
                "/usr/bin/printf %s {} > {}",
                quote(nonce),
                quote(&format!("{workspace}/{write}"))
            ),
            "succeeded",
            "none",
            Some(0),
        ),
        command(
            "original_repo_write",
            format!(
                "/usr/bin/touch -- {}",
                quote(&format!("{fixture_root}/{write}"))
            ),
            "denied",
            "os",
            Some(1),
        ),
        command(
            "service_data_write",
            format!("/usr/bin/touch -- {}", quote(service_sentinel)),
            "denied",
            "os",
            Some(1),
        ),
    ];
    if provider == Provider::Codex {
        outcomes.push(command(
            "permission_delivery",
            format!(
                "/usr/bin/touch -- {}",
                quote(&format!("{workspace}/runtime-permission-{nonce}.txt"))
            ),
            "denied",
            "provider",
            None,
        ));
    }
    outcomes.push(command(
        "human_control_read",
        format!("/bin/test -r {}", quote(control)),
        "denied",
        "os",
        Some(1),
    ));
    serde_json::Value::Array(outcomes)
}

fn start_synthetic_runtime_probe(
    fixture: &Fixture,
    admission: &str,
    role: RoleKind,
    resume_observed: bool,
) -> (RoleLaunchContext, String, String, String, String) {
    let role_name = role.to_string();
    let (attempt, nonce, control): (String, String, String) = fixture
        .connection()
        .query_row(
            "SELECT attempt_id,nonce,control_socket_path FROM trip_runtime_probes WHERE admission_id=?1 AND role=?2",
            params![admission, role_name],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    let context = fixture
        .store
        .trip_setup_role_launch_context(&attempt, role, true)
        .unwrap();
    let prompt = agenticjira::trip::setup_launch_prompt(&fixture.store, &attempt, role).unwrap();
    let launch = if context.config.provider == Provider::Claude {
        let runtime = capability_runtime(fixture);
        let policy = runtime_probe_policy_for_test(fixture, admission, role, &context.workspace);
        providers::prepare_runtime_probe_role_launch_with_bundles(
            Provider::Claude,
            role,
            &context.config.model,
            &context.config.effort,
            &context.workspace,
            &prompt,
            &runtime.role_socket,
            &context.token,
            &context.role_generation_id,
            &context.session_id,
            None,
            &runtime.hooks,
            &runtime.executable,
            &policy,
            fixture
                .synthetic_bundles
                .as_ref()
                .unwrap_or(&agenticjira::provider_compatibility::BundleSet::embedded()),
        )
        .unwrap()
        .config
    } else {
        confined_launch(fixture, &attempt, &context, role, &prompt)
    };
    fixture.reserve_role(&context, &launch);
    fixture
        .store
        .bind_invocation_input(&context.session_id, &prompt, None)
        .unwrap();
    fixture.execute(
        "UPDATE trip_runtime_probes SET state='running',session_id=?1 WHERE admission_id=?2 AND role=?3",
        params![context.session_id, admission, role_name],
    );
    fixture.execute(
        "UPDATE trip_runtime_admissions SET state='running' WHERE id=?1",
        params![admission],
    );
    fixture.execute(
        "UPDATE sessions SET status='running',launch_state='started',validation_cell='trip_runtime_probe',
           native_session_id=?1,process_identity_json='{}',hook_trust_state='observed_unverified',resume_count=?2 WHERE id=?3",
        params![format!("synthetic-runtime-native-{admission}-{role_name}"), i64::from(resume_observed), context.session_id],
    );
    fixture.execute(
        "UPDATE role_generations SET status='running' WHERE id=?1",
        params![context.role_generation_id],
    );
    fixture.execute(
        "UPDATE role_settings SET effective_generation_id=?1 WHERE task_id=?2 AND role=?3 AND revision=?4",
        params![context.role_generation_id, context.task_id, role_name, context.settings_revision],
    );
    let (fixture_root, service_sentinel, cmux_socket): (String, String, Option<String>) = fixture
        .connection()
        .query_row(
            "SELECT fixture_root,service_sentinel_path,cmux_socket_path FROM trip_runtime_probes
             WHERE admission_id=?1 AND role=?2",
            params![admission, role_name],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    let fake_native_id = format!("synthetic-runtime-native-{admission}-{role_name}");
    let mut fake_outcomes = if role == RoleKind::Implementer {
        implementer_runtime_outcomes(
            context.config.provider,
            context.workspace.to_string_lossy().as_ref(),
            &fixture_root,
            &service_sentinel,
            &nonce,
            &control,
        )
    } else {
        readonly_runtime_outcomes(
            context.workspace.to_string_lossy().as_ref(),
            &nonce,
            &control,
        )
    };
    if let Some(cmux_socket) = cmux_socket {
        let quote = |value: &str| format!("'{}'", value.replace('\'', "'\"'\"'"));
        fake_outcomes
            .as_array_mut()
            .unwrap()
            .push(serde_json::json!({
                "operation_id":"cmux_socket_connect",
                "command":format!(
                    "{} unix-connect-probe --path {}",
                    quote(std::env::current_exe().unwrap().to_string_lossy().as_ref()),
                    quote(&cmux_socket)
                ),
                "attempted":true,"exit_status":1,"result":"denied",
                "denial_source":"os","authentication_source":"native_session"
            }));
    }
    let insert_fake_hook = |event_name: &str,
                            ordinal: usize,
                            tool_input: Option<serde_json::Value>| {
        let mut payload = serde_json::json!({
            "synthetic_fixture":true,
            "native_proof":false,
            "hook_event_name":event_name,
            "session_id":fake_native_id,
            "cwd":context.workspace.to_string_lossy(),
        });
        if let Some(tool_input) = tool_input {
            payload["tool_name"] =
                serde_json::json!(if context.config.provider == Provider::Claude {
                    "Bash"
                } else {
                    "shell"
                });
            payload["tool_input"] = tool_input;
        }
        if event_name == "PreToolUse" {
            payload["tool_use_id"] = serde_json::json!(format!("synthetic-runtime-tool-{ordinal}"));
        }
        fixture.execute(
            "INSERT INTO hook_events(id,session_id,role_generation_id,provider,event_name,
               native_session_id,payload_json,peer_pid,peer_process_group_id,peer_start_marker,
               provenance_state,received_at)
             VALUES(?1,?2,?3,?4,?5,?6,?7,1,1,'synthetic-fake-hook',
               'managed_process_group_untrusted_payload','2026-01-01T00:00:00Z')",
            params![
                format!(
                    "synthetic-runtime-hook-{}-{event_name}-{ordinal}",
                    context.session_id
                ),
                context.session_id,
                context.role_generation_id,
                context.config.provider.to_string(),
                event_name,
                fake_native_id,
                serde_json::to_string(&payload).unwrap()
            ],
        );
    };
    insert_fake_hook("SessionStart", 0, None);
    insert_fake_hook("UserPromptSubmit", 0, None);
    for (ordinal, outcome) in fake_outcomes.as_array().unwrap().iter().enumerate() {
        insert_fake_hook(
            "PreToolUse",
            ordinal,
            Some(serde_json::json!({"command":outcome["command"]})),
        );
    }
    if role == RoleKind::Implementer && context.config.provider == Provider::Codex {
        let command = fake_outcomes
            .as_array()
            .unwrap()
            .iter()
            .find(|outcome| outcome["operation_id"] == "permission_delivery")
            .unwrap()["command"]
            .clone();
        insert_fake_hook(
            "PermissionRequest",
            fake_outcomes.as_array().unwrap().len(),
            Some(serde_json::json!({
                "command":command,
                "description":"synthetic permission delivery denial"
            })),
        );
    }
    if resume_observed {
        let hook_boundary: i64 = fixture
            .connection()
            .query_row(
                "SELECT MAX(rowid) FROM hook_events WHERE session_id=?1",
                params![context.session_id],
                |row| row.get(0),
            )
            .unwrap();
        fixture.execute(
            "INSERT INTO resume_invocations(id,session_id,resume_ordinal,transcript_epoch,
               launch_config_json,capability_key,capability_identity_json,state,
               hook_event_boundary_rowid,created_at,updated_at)
             SELECT ?1,id,1,transcript_epoch,launch_config_json,capability_key,
               capability_identity_json,'running',?2,'2026-01-01T00:00:00Z',
               '2026-01-01T00:00:00Z' FROM sessions WHERE id=?3",
            params![
                uuid::Uuid::new_v4().to_string(),
                hook_boundary,
                context.session_id
            ],
        );
        insert_fake_hook("SessionStart", 1, None);
        insert_fake_hook("UserPromptSubmit", 1, None);
    }
    (context, attempt, nonce, control, prompt)
}

#[test]
fn runtime_capacity_rejection_preserves_unspent_authorization() {
    let (fixture, paths, _, admission) = authorized_runtime_fixture("runtime-capacity-retry");
    let (manager, ..) =
        start_synthetic_runtime_probe(&fixture, &admission, RoleKind::Manager, false);
    let (verifier, ..) =
        start_synthetic_runtime_probe(&fixture, &admission, RoleKind::FinalReviewer, false);
    let application = Application::new(
        paths,
        fixture.store.clone(),
        PathBuf::from("/usr/bin/false"),
    )
    .unwrap();
    let snapshot = || {
        fixture
            .connection()
            .query_row(
                "SELECT p.state,p.failure_reason,p.session_id,permit.state,
            (SELECT COUNT(*) FROM sessions), (SELECT COUNT(*) FROM launch_permits)
         FROM trip_runtime_probes p JOIN trip_setup_permits permit
           ON permit.attempt_id=p.attempt_id AND permit.role=p.role
         WHERE p.admission_id=?1 AND p.role='explorer'",
                params![admission],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Option<String>>(1)?,
                        row.get::<_, Option<String>>(2)?,
                        row.get::<_, String>(3)?,
                        row.get::<_, i64>(4)?,
                        row.get::<_, i64>(5)?,
                    ))
                },
            )
            .unwrap()
    };
    let before = snapshot();
    let error = application
        .dispatch_runtime_probe("capacity-rejected", &admission, RoleKind::Explorer)
        .unwrap_err();
    assert!(error.to_string().contains("role capacity is full"));
    assert_eq!(
        snapshot(),
        before,
        "capacity rejection must not consume an unlaunched probe"
    );
    fixture.finish_role(&manager);
    fixture.finish_role(&verifier);
    let retry = application
        .dispatch_runtime_probe("capacity-retry", &admission, RoleKind::Explorer)
        .unwrap_err()
        .to_string();
    assert!(
        retry.contains("launch wrapper") || retry.contains("provider spawn handshake"),
        "retry did not reach launch: {retry}"
    );
    assert_eq!(
        snapshot().0,
        "failed",
        "actual launch failures still require a fresh scope"
    );
}

fn authorized_runtime_fixture(name: &str) -> (Fixture, InstancePaths, String, String) {
    authorized_runtime_fixture_with_bundles(name, false)
}

fn authorized_runtime_fixture_with_bundles(
    name: &str,
    synthetic_claude: bool,
) -> (Fixture, InstancePaths, String, String) {
    let fixture = if synthetic_claude {
        Fixture::new(name).with_synthetic_claude()
    } else {
        Fixture::new(name)
    };
    let repository = fixture.repository("repo");
    let project = add_project(&fixture, repository, name);
    let paths = instance_paths(&fixture);
    let (setup, runtime_project): (String, String) = fixture
        .connection()
        .query_row(
            "SELECT id,fixture_project_id FROM trip_setup_operations
             WHERE project_id=?1 AND state='activated'",
            params![project],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    let validation_task = format!("synthetic-runtime-task-{project}");
    fixture.execute(
        "INSERT INTO tasks(id,project_id,title,description,acceptance_criteria_json,priority,
           manual_order,lifecycle,attention,version,created_at,updated_at,role_overrides_json)
         VALUES(?1,?2,'Synthetic runtime validation','Internal runtime capability lifecycle',
           '[]',0,0,'validation','paused',1,'2026-01-01T00:00:00Z',
           '2026-01-01T00:00:00Z','{}')",
        params![validation_task, runtime_project],
    );
    fixture.execute(
        "UPDATE trip_setup_operations SET validation_task_id=?1 WHERE id=?2",
        params![validation_task, setup],
    );
    let admission = execute_trip(
        &fixture,
        &paths,
        &format!("prepare-{name}"),
        &TripHumanAction::PrepareRuntimeAdmission {
            project_id: project.clone(),
            task_id: None,
            role: None,
            settings_revision: None,
            cmux_socket_path: None,
            expected_version: 2,
        },
    )
    .unwrap();
    authorize_runtime_admission(&fixture, &paths, &format!("authorize-{name}"), &admission);
    (fixture, paths, project, admission.entity_id)
}

